import { HttpClient, HttpHeaders } from "@angular/common/http";
import { Component, OnInit, inject } from "@angular/core";
import { Task } from "../Model/Task";
import { map } from "rxjs/operators";
import { TaskService } from "../services/task.service";

@Component({
  selector: "app-dashboard",
  templateUrl: "./dashboard.component.html",
  styleUrls: ["./dashboard.component.css"],
})
export class DashboardComponent implements OnInit {
  http: HttpClient = inject(HttpClient);
  showCreateTaskForm: boolean = false;
  allTasks: any[] = [];
  taskService: TaskService = inject(TaskService);
  editMode: boolean = false;
  selectedTask: Task;
  currentTaskId: string = "";
  isLoading: boolean = false;

  OpenCreateTaskForm() {
     this.showCreateTaskForm = true;
    this.editMode = false;
    this.selectedTask = {title: '', desc: '', assignedTo: '', createdAt: '', priority: '', status: ''}
  }

  ngOnInit() {
    this.fetchAllTasks();
  }

  CloseCreateTaskForm() {
    this.showCreateTaskForm = false;
    this.editMode = false;
  }
  CreateOrUpdateTask(taskData: any) {
     if(!this.editMode)
      this.taskService.CreateTask(taskData);
    else
      this.taskService.UpdateTask(this.currentTaskId, taskData);

  }

  FetchAllTaskClicked() {
    this.fetchAllTasks();
  }

  DeleteTask(taskId: string) {
    this.taskService.DeleteTask(taskId);
  }
  OnEditTaskClicked(taskId: string) {
    this.currentTaskId = taskId;
    this.showCreateTaskForm = true;
    this.editMode = true;
    this.selectedTask = this.allTasks.find((task) => {
      return task.id === taskId;
    });
  }
  showCurrentTaskDetails(taskId: string) {}

  private fetchAllTasks() {
    this.isLoading = true;
    this.taskService.GetAlltasks().subscribe((response) => {
      this.allTasks = response;
      this.isLoading = false;
    });
  }

  DeleteAllTask() {
    this.taskService.DeleteAllTasks();
  }
}
